use vstd::prelude::*;

verus! {
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            0 < n < list.len(),
        ensures
            new_list.len() == list.len(),
            forall |i: usize| 0 <= i < new_list.len() ==> new_list[i] == if i < list.len() - n { list[i + n] } else { list[i - (list.len() - n)] },
    {
        let len = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        
        // Append elements from index n to the end of the list
        let mut i: usize = n;
        while i < len
            invariant
                0 <= i <= len,
                new_list.len() == i - n,
                new_list.len() <= len,
            decreases len - i,
        {
            new_list.push(list[i]);
            i = i + 1;
        }

        // Append elements from index 0 to n-1
        let mut j: usize = 0;
        while j < n
            invariant
                0 <= j <= n,
                new_list.len() == len - n + j,
                new_list.len() <= len,
            decreases n - j,
        {
            new_list.push(list[j]);
            j = j + 1;
        }

        new_list
    }
}
